!function(){const e=document.querySelector(".uc-privacy-policy");if(!e)return;if(!e.querySelector(".uc-policy-loading"))return;const t=e.getAttribute("data-policy-id"),r=navigator.language||navigator.userLanguage;if(!t)return;fetch("https://policygenerator.usercentrics.eu/api/embedding?id="+t+"&language="+r).then(function(e){if(!e.ok)throw new Error("Failed to fetch policy: "+e.statusText);return e.text()}).then(function(t){e.innerHTML=t}).catch(function(t){e.innerHTML='<div class="ppguc-error-message"><p><strong>Unable to load privacy policy.</strong></p><p>Please try refreshing the page or contact support if the problem persists.</p></div>'})}();
